import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { randomBytes } from "node:crypto";
import { dirname } from "node:path";

export function createStore(file) {
  let queue = Promise.resolve();

  async function load() {
    try {
      const data = JSON.parse(await readFile(file, "utf8"));
      if (!Array.isArray(data)) throw new Error(`${file} does not contain a book array`);
      return data;
    } catch (err) {
      if (err.code === "ENOENT") return [];
      throw err;
    }
  }

  async function save(books) {
    await mkdir(dirname(file), { recursive: true });
    const tmp = `${file}.${process.pid}.tmp`;
    await writeFile(tmp, JSON.stringify(books, null, 2) + "\n");
    await rename(tmp, file);
  }

  function enqueue(fn) {
    const run = queue.then(fn);
    queue = run.then(
      () => {},
      () => {}
    );
    return run;
  }

  return {
    list() {
      return enqueue(load);
    },

    get(id) {
      return enqueue(async () => (await load()).find((b) => b.id === id) ?? null);
    },

    add({ title, author = "", notes = "" }) {
      return enqueue(async () => {
        const books = await load();
        const book = {
          id: randomBytes(8).toString("hex"),
          title,
          author,
          notes,
          status: "reading",
          createdAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        await save(books);
        return book;
      });
    },

    finish(id) {
      return enqueue(async () => {
        const books = await load();
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        if (book.status !== "finished") {
          book.status = "finished";
          book.finishedAt = new Date().toISOString();
          await save(books);
        }
        return book;
      });
    },
  };
}

export function escapeHtml(value) {
  return String(value).replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]
  );
}

const CSS = `
:root { color-scheme: light dark; }
* { box-sizing: border-box; }
body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2.5rem auto; padding: 0 1rem; line-height: 1.55; }
h1 { font-size: 1.5rem; margin-bottom: 0.25rem; }
h2 { font-size: 1rem; text-transform: uppercase; letter-spacing: 0.05em; color: #888; margin-top: 2rem; }
.site-title { margin-bottom: 1.5rem; }
.site-title a { text-decoration: none; color: inherit; font-weight: 600; }
ul.books { list-style: none; margin: 0; padding: 0; }
ul.books li { display: flex; align-items: baseline; gap: 0.6rem; padding: 0.5rem 0; border-bottom: 1px solid rgba(128,128,128,.25); }
ul.books .title { flex: 1; }
ul.books .meta { font-size: 0.9rem; }
.meta, .hint { color: #888; }
form.inline { display: inline; margin: 0; }
button { font: inherit; font-size: 0.85rem; padding: 0.2rem 0.6rem; border: 1px solid #888; border-radius: 6px; background: transparent; color: inherit; cursor: pointer; }
button:hover { border-color: currentColor; }
.add-book { display: grid; gap: 0.6rem; }
.add-book label { display: grid; gap: 0.2rem; font-size: 0.9rem; }
.add-book input, .add-book textarea, .share input { font: inherit; padding: 0.45rem 0.6rem; border: 1px solid #888; border-radius: 6px; background: transparent; color: inherit; }
.add-book textarea { min-height: 5rem; resize: vertical; }
.add-book button { justify-self: start; font-size: 0.95rem; padding: 0.4rem 1rem; }
.error { color: #c0392b; }
.notes { white-space: pre-wrap; border-left: 3px solid rgba(128,128,128,.4); padding-left: 0.75rem; }
.share input { width: 100%; font-size: 0.9rem; }
.actions { display: flex; gap: 0.75rem; align-items: center; margin-top: 1.5rem; }
.actions button { font-size: 0.95rem; padding: 0.4rem 1rem; }
`;

function layout(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${CSS}</style>
</head>
<body>
${content}
</body>
</html>`;
}

function shortDate(iso) {
  return iso ? iso.slice(0, 10) : "";
}

export function homePage({ books, error }) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => String(b.finishedAt ?? "").localeCompare(String(a.finishedAt ?? "")));

  const list = (items, withFinish) => `<ul class="books">${items
    .map(
      (b) => `<li>
      <span class="title"><a href="/books/${b.id}">${escapeHtml(b.title)}</a></span>
      <span class="meta">${b.author ? `by ${escapeHtml(b.author)}` : ""}${
        withFinish || !b.finishedAt ? "" : ` · finished ${shortDate(b.finishedAt)}`
      }</span>
      ${
        withFinish
          ? `<form class="inline" method="post" action="/books/${b.id}/finish"><button>Finished</button></form>`
          : ""
      }
    </li>`
    )
    .join("")}</ul>`;

  return layout(
    "Bookshelf",
    `<nav class="site-title"><a href="/">Bookshelf</a></nav>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
<h2>Currently reading</h2>
<section id="reading">${
      reading.length ? list(reading, true) : `<p class="hint">Nothing here yet — add a book below.</p>`
    }</section>
<h2>Finished</h2>
<section id="finished">${
      finished.length ? list(finished, false) : `<p class="hint">No finished books yet.</p>`
    }</section>
<h2>Add a book</h2>
<form class="add-book" method="post" action="/books">
  <label>Title <input name="title" required maxlength="300"></label>
  <label>Author <input name="author" maxlength="200"></label>
  <label>Notes <textarea name="notes" rows="4"></textarea></label>
  <button type="submit">Add book</button>
</form>`
  );
}

export function bookPage({ book, url }) {
  const status =
    book.status === "finished"
      ? `Finished${book.finishedAt ? ` on ${shortDate(book.finishedAt)}` : ""}`
      : "Currently reading";
  return layout(
    book.title,
    `<nav class="site-title"><a href="/">Bookshelf</a></nav>
<h1>${escapeHtml(book.title)}</h1>
<p class="meta">${book.author ? `by ${escapeHtml(book.author)} &middot; ` : ""}${status}</p>
${book.notes ? `<h2>Notes</h2>\n<p class="notes">${escapeHtml(book.notes)}</p>` : ""}
${
      book.status === "finished"
        ? ""
        : `<div class="actions"><form method="post" action="/books/${book.id}/finish"><button>Mark as finished</button></form></div>`
    }
<h2>Share</h2>
<p class="hint">Anyone with this link can view this book.</p>
<div class="share"><input readonly value="${escapeHtml(url)}" onclick="this.select()"></div>`
  );
}

export function notFoundPage(message) {
  return layout(
    "Not found",
    `<nav class="site-title"><a href="/">Bookshelf</a></nav>
<h1>Not found</h1>
<p class="meta">${escapeHtml(message)}</p>
<p><a href="/">Back to all books</a></p>`
  );
}

import http from "node:http";
import { pathToFileURL } from "node:url";
import { createStore } from "./store.js";
import { homePage, bookPage, notFoundPage } from "./views.js";

const BOOK_PATH = /^\/books\/([^/]+)$/;
const FINISH_PATH = /^\/books\/([^/]+)\/finish$/;

function html(res, status, body) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    let size = 0;
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > 64 * 1024) {
        reject(new Error("Payload too large"));
        req.destroy();
        return;
      }
      body += chunk;
    });
    req.on("end", () => resolve(new URLSearchParams(body)));
    req.on("error", reject);
  });
}

export function createRequestHandler({ dataFile }) {
  const store = createStore(dataFile);

  return async function handler(req, res) {
    try {
      const url = new URL(req.url, "http://internal");
      const path = url.pathname;

      if (req.method === "GET" && path === "/") {
        const books = await store.list();
        html(res, 200, homePage({ books, error: url.searchParams.get("error") }));
        return;
      }

      if (req.method === "POST" && path === "/books") {
        const form = await readForm(req);
        const title = (form.get("title") ?? "").trim();
        if (!title) {
          redirect(res, "/?error=" + encodeURIComponent("Title is required"));
          return;
        }
        const book = await store.add({
          title,
          author: (form.get("author") ?? "").trim(),
          notes: (form.get("notes") ?? "").trim(),
        });
        redirect(res, `/books/${book.id}`);
        return;
      }

      const bookMatch = path.match(BOOK_PATH);
      if (req.method === "GET" && bookMatch) {
        const book = await store.get(decodeURIComponent(bookMatch[1]));
        if (!book) {
          html(res, 404, notFoundPage("No book with that link exists."));
          return;
        }
        const origin = `${req.socket.encrypted ? "https" : "http"}://${req.headers.host ?? "localhost"}`;
        html(res, 200, bookPage({ book, url: `${origin}/books/${book.id}` }));
        return;
      }

      const finishMatch = path.match(FINISH_PATH);
      if (req.method === "POST" && finishMatch) {
        const book = await store.finish(decodeURIComponent(finishMatch[1]));
        if (!book) {
          html(res, 404, notFoundPage("No book with that link exists."));
          return;
        }
        redirect(res, `/books/${book.id}`);
        return;
      }

      html(res, 404, notFoundPage("That page does not exist."));
    } catch (err) {
      const status = /too large/i.test(err.message ?? "") ? 413 : 500;
      html(res, status, notFoundPage(status === 413 ? "Form data too large." : "Something went wrong."));
    }
  };
}

export function createServer({ dataFile }) {
  return http.createServer(createRequestHandler({ dataFile }));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const dataFile = process.env.DATA_FILE ?? "./books.json";
  const port = Number(process.env.PORT ?? 3000);
  createServer({ dataFile }).listen(port, () => {
    console.log(`Bookshelf running at http://localhost:${port} (data: ${dataFile})`);
  });
}

import { afterAll, beforeAll, expect, test } from "vitest";
import http from "node:http";
import { mkdtemp, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createRequestHandler } from "./server.js";

let server;
let base;
let dataFile;
let bookId;

beforeAll(async () => {
  dataFile = join(await mkdtemp(join(tmpdir(), "bookshelf-")), "books.json");
  server = http.createServer(createRequestHandler({ dataFile }));
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterAll(() => server.close());

function post(path, fields) {
  return fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    redirect: "manual",
  });
}

test("rejects a book with an empty title", async () => {
  const res = await post("/books", { title: "   ", author: "Nobody" });
  expect(res.status).toBe(303);
  expect(res.headers.get("location")).toBe("/?error=Title%20is%20required");
});

test("adds a book and shows its page", async () => {
  const res = await post("/books", {
    title: "Dune",
    author: "Frank Herbert",
    notes: "Great world-building.\nSecond pass soon.",
  });
  expect(res.status).toBe(303);
  const location = res.headers.get("location");
  expect(location).toMatch(/^\/books\/[a-f0-9]{16}$/);
  bookId = location.split("/")[2];

  const page = await fetch(base + location);
  const html = await page.text();
  expect(html).toContain("Dune");
  expect(html).toContain("Frank Herbert");
  expect(html).toContain("Great world-building.");
  expect(html).toContain("Currently reading");
});

test("new book appears under currently reading on the home page", async () => {
  const html = await (await fetch(base + "/")).text();
  const reading = html.split('id="finished"')[0];
  expect(reading).toContain("Dune");
  expect(reading).toContain(`/books/${bookId}/finish`);
});

test("marks a book as finished", async () => {
  const res = await post(`/books/${bookId}/finish`, {});
  expect(res.status).toBe(303);
  expect(res.headers.get("location")).toBe(`/books/${bookId}`);

  const page = await (await fetch(base + `/books/${bookId}`)).text();
  expect(page).toContain("Finished");

  const home = await (await fetch(base + "/")).text();
  const finished = home.split('id="finished"')[1];
  expect(finished).toContain("Dune");
});

test("books survive a restart via the JSON file", async () => {
  const saved = JSON.parse(await readFile(dataFile, "utf8"));
  expect(saved).toHaveLength(1);
  expect(saved[0]).toMatchObject({ title: "Dune", author: "Frank Herbert", status: "finished" });
  expect(saved[0].finishedAt).toBeTruthy();

  const restarted = http.createServer(createRequestHandler({ dataFile }));
  await new Promise((resolve) => restarted.listen(0, "127.0.0.1", resolve));
  try {
    const home = await (await fetch(`http://127.0.0.1:${restarted.address().port}/`)).text();
    expect(home).toContain("Dune");
  } finally {
    restarted.close();
  }
});

test("unknown book link returns 404", async () => {
  const res = await fetch(base + "/books/deadbeefdeadbeef");
  expect(res.status).toBe(404);
});

